# C:Users\u000BladeOneDriveDocumentosGitHubStrategicFlow\backendsrcmodulescrmautomation.pyimport asyncioimport loggingfrom datetime import datetime, timedeltafrom typing import Optionalfrom .notifications import NotificationServicelogger = logging.getLogger("crm_automation")# ============================================# 🤖 AUTOMAÇÃO 1: Workflow quando oportunidade muda de estágio# ============================================# 👉 TRIGGER: WHEN opportunity.stage = 'fechado_positivo'# 👉 ACTION 1: Criar projeto automaticamente# 👉 ACTION 2: Enviar email de welcome# 👉 ACTION 3: Criar evento no Calendarasync def on_opportunity_stage_changed(    opportunity_id: int,    old_stage: str,    new_stage: str,    tenant_id: str):    """    Workflow automático quando oportunidade muda de estágio    👉 TRIGGER: opportunity.stage UPDATE    """    from core.database import get_db    from .service import create_project, get_opportunities    from .notifications import NotificationService        db = await get_db()        # 👉 GET OPORTUNIDADE    opp = await get_opportunities(opportunity_id, tenant_id)    if not opp:        return        opp = opp[0]        print(f"🤖 AUTOMAÇÃO: Oportunidade {opp.title} mudou de {old_stage} -> {new_stage}")        # ✅ AUTOMAÇÃO 1: Quando fechar positivo -> criar projeto automaticamente    if new_stage == 'fechado_positivo' and old_stage != 'fechado_positivo':        print("🤖 AUTOMAÇÃO: Contrato fechado -> Criando projeto automaticamente")                # 👉 CREATE PROJETO (conversão automática)        project = Project(            id=0,            client_id=opp.client_id,            opportunity_id=opp.id,            name=f"Projeto: {opp.title}",            description=opp.description,            scope="Recebimento, Picking, Estoque, Expedição",  # Default scope            status="planejamento",            priority="alta",            budget=opp.value_closed,            hours_contracted=int(opp.value_closed / 500),  # Estimativa: R$ 500/hora            manager="Vlademir"        )                await create_project(project, tenant_id)                print("✅ Projeto criado automaticamente")        # ✅ AUTOMAÇÃO 2: Enviar email de welcome ao cliente    if new_stage == 'fechado_positivo':        notification_service = NotificationService()                # 👉 GET CLIENTE        client = await db.fetchone(            "SELECT * FROM clients WHERE id = $1", opp.client_id        )                if client and client["email"]:            await notification_service.send_welcome_email(                client_email=client["email"],                client_name=client["razao_social"]            )                        print("✅ Email de welcome disparado")        # ✅ AUTOMAÇÃO 3: Enviar push notification    push_service = PushNotificationService(ws_manager)    await push_service.send_push_notification(        tenant_id=tenant_id,        notification_type="opportunity_stage_change",        title=f"Oportunidade: {opp.title}",        message=f"Movida para estágio: {new_stage}",        data={"opportunity_id": opp.id, "stage": new_stage}    )# ============================================# 🤖 AUTOMAÇÃO 2: Reminder automático de next_action# ============================================# 👉 TRIGGER: WHEN interactions.next_action_date = TODAY# 👉 ACTION: Enviar email reminderasync def on_next_action_due(interaction_id: int, tenant_id: str):    """    Reminder automático de next_action    👉 TRIGGER: interactions.next_action_date = TODAY    """    from core.database import get_db    from .notifications import NotificationService        db = await get_db()        # 👉 GET INTERACTION    interaction = await db.fetchone(        """        SELECT * FROM interactions WHERE id = $1 AND tenant_id = $2        """,        interaction_id, tenant_id    )        if not interaction:        return        notification_service = NotificationService()        # 👉 SEND EMAIL REMINDER    await notification_service._send_email(        to="vlademir@strategicflow.com",        subject=f"⏰ Reminder: {interaction['next_action']}",        body=f"""        Task pendente: {interaction['next_action']}        Data: {interaction['next_action_date']}        Interação: {interaction['title']}        Descrição: {interaction['description']}        """    )        print(f"✅ Reminder disparado: {interaction['next_action']}")# ============================================# 🤖 AUTOMAÇÃO 3: SLA de resposta (30 dias sem interação)# ============================================# 👉 TRIGGER: WHEN client.last_interaction > 30 days# 👉 ACTION: Enviar email de follow-upasync def on_client_sla_breach(client_id: int, tenant_id: str):    """    SLA de resposta quebrado (30+ dias sem interação)    👉 TRIGGER: client.last_interaction > 30 days    """    from core.database import get_db    from .notifications import NotificationService        db = await get_db()        # 👉 GET CLIENTE    client = await db.fetchone(        "SELECT * FROM clients WHERE id = $1 AND tenant_id = $2",        client_id, tenant_id    )        if not client:        return        notification_service = NotificationService()        # 👉 SEND EMAIL FOLLOW-UP    await notification_service._send_email(        to=client["email"],        subject="👋 Follow-up: Como está seu projeto?",        body=f"""        Olá {client['razao_social']},                Estamos fazendo um follow-up para saber como está seu projeto.                Há 30+ dias não tivemos interação. Queremos garantir que tudo está indo bem!                Por favor, confirme se precisa de algum apoio adicional.                Atenciosamente,        Vlademir Oliveira        """    )        print(f"✅ Follow-up disparado: {client['razao_social']}")